{
  "id": "media.library.scan",
  "title": "media.library.scan",
  "description": "Index video files under an authorized native root: enumeration, probe, head hash and file locations only. Does not search providers, infer episodes or create identification tasks. requestId deduplicates submission.",
  "effect": "write",
  "inputSchema": {
    "type": "object",
    "properties": {
      "root": {
        "type": "string",
        "minLength": 1
      },
      "requestId": {
        "type": "string",
        "minLength": 1
      }
    },
    "required": [
      "root",
      "requestId"
    ],
    "additionalProperties": false
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "job": {
        "type": "object",
        "properties": {
          "jobId": {
            "type": "string"
          },
          "state": {
            "type": "string"
          },
          "revision": {
            "type": "integer"
          }
        },
        "required": [
          "jobId",
          "state",
          "revision"
        ],
        "additionalProperties": false
      }
    },
    "required": [
      "job"
    ],
    "additionalProperties": false
  }
}

