{
  "id": "download.add",
  "title": "add download",
  "description": "Accept source or sources: magnet URIs, HTTP(S) torrent URLs or local .torrent paths. Optional downloadDirectory and createFolderForTask override defaults for these new tasks without changing settings. Returns queued jobs after metadata validation, deduplicated by backend and infoHash; an existing task keeps its original directory. Batch results preserve input order and individual failures.",
  "effect": "write",
  "inputSchema": {
    "type": "object",
    "properties": {
      "source": {
        "type": "string",
        "minLength": 1
      },
      "sources": {
        "type": "array",
        "items": {
          "type": "string",
          "minLength": 1
        }
      },
      "backend": {
        "type": "object",
        "properties": {
          "kind": {
            "type": "string",
            "minLength": 1
          },
          "id": {
            "type": "string",
            "minLength": 1
          }
        },
        "required": [
          "kind"
        ],
        "additionalProperties": false
      },
      "downloadDirectory": {
        "type": "string",
        "minLength": 1
      },
      "createFolderForTask": {
        "type": "boolean"
      }
    },
    "additionalProperties": false,
    "oneOf": [
      {
        "required": [
          "source"
        ]
      },
      {
        "required": [
          "sources"
        ]
      }
    ]
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "job": {
        "type": "object",
        "properties": {
          "jobId": {
            "type": "string"
          },
          "type": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "state": {
            "type": "string",
            "enum": [
              "queued",
              "running",
              "paused",
              "needs_decision",
              "waiting_retry",
              "interrupted",
              "cancelling",
              "succeeded",
              "failed",
              "cancelled"
            ]
          },
          "phase": {
            "type": "string"
          },
          "progress": {
            "type": "object",
            "properties": {
              "completed": {
                "type": "number",
                "minimum": 0
              },
              "total": {
                "type": "number",
                "minimum": 0
              },
              "unit": {
                "type": "string"
              }
            },
            "required": [
              "completed",
              "unit"
            ],
            "additionalProperties": false
          },
          "createdAt": {
            "type": "string"
          },
          "updatedAt": {
            "type": "string"
          },
          "ownerDeviceId": {
            "type": "string"
          },
          "revision": {
            "type": "integer",
            "minimum": 0
          },
          "error": {
            "type": "object",
            "properties": {
              "code": {
                "type": "string"
              },
              "message": {
                "type": "string"
              },
              "retryable": {
                "type": "boolean"
              }
            },
            "required": [
              "code",
              "message",
              "retryable"
            ],
            "additionalProperties": false
          },
          "decision": {
            "type": "object",
            "properties": {
              "prompt": {
                "type": "string"
              },
              "options": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "label": {
                      "type": "string"
                    },
                    "detail": {
                      "type": "string"
                    },
                    "call": {
                      "type": "object",
                      "properties": {
                        "action": {
                          "type": "string"
                        },
                        "input": {
                          "type": "object"
                        }
                      },
                      "required": [
                        "action",
                        "input"
                      ],
                      "additionalProperties": false
                    }
                  },
                  "required": [
                    "label",
                    "call"
                  ],
                  "additionalProperties": false
                }
              }
            },
            "required": [
              "prompt",
              "options"
            ],
            "additionalProperties": false
          },
          "receipt": {
            "type": "object",
            "properties": {
              "verification": {
                "type": "string",
                "enum": [
                  "verified",
                  "acknowledged",
                  "unverified"
                ]
              },
              "details": {
                "type": "object"
              },
              "cancellation": {
                "type": "object",
                "properties": {
                  "requestedAt": {
                    "type": "string"
                  },
                  "phase": {
                    "type": "string"
                  },
                  "sideEffectCommitted": {
                    "type": "boolean"
                  },
                  "afterCommit": {
                    "type": "boolean"
                  }
                },
                "required": [
                  "requestedAt",
                  "phase",
                  "sideEffectCommitted",
                  "afterCommit"
                ],
                "additionalProperties": false
              }
            },
            "required": [
              "verification",
              "details"
            ],
            "additionalProperties": false
          },
          "backend": {
            "type": "object",
            "properties": {
              "kind": {
                "type": "string",
                "minLength": 1
              },
              "id": {
                "type": "string",
                "minLength": 1
              }
            },
            "required": [
              "kind"
            ],
            "additionalProperties": false
          }
        },
        "required": [
          "jobId",
          "type",
          "title",
          "state",
          "phase",
          "progress",
          "createdAt",
          "updatedAt",
          "ownerDeviceId",
          "revision",
          "backend"
        ],
        "additionalProperties": true
      },
      "task": {
        "type": [
          "object",
          "null"
        ],
        "properties": {
          "handle": {
            "type": "string",
            "minLength": 1
          },
          "infoHash": {
            "type": "string",
            "minLength": 1
          },
          "title": {
            "type": "string"
